import React, { useState } from 'react'
import IncidentTable from '../IncidentTable/IncidentTable'
import RecommendationCard from '../RecommendationCard/RecommendationCard'
import AgentTrace from '../AgentTrace/AgentTrace'
import './ChatMessage.css'

export default function ChatMessage({ message }) {
  const [openSection, setOpenSection] = useState(null)

  if (message.role === 'user') {
    return (
      <div className="chat-msg chat-msg--user">
        <div className="chat-bubble chat-bubble--user">{message.content}</div>
      </div>
    )
  }

  if (message.role === 'error') {
    return (
      <div className="chat-msg chat-msg--error">
        <div className="chat-bubble chat-bubble--error">{message.content}</div>
      </div>
    )
  }

  const { answer, retrieved_incidents, recommendations, agent_findings, anomaly_correlations, confidence_score } = message.content

  const toggle = (section) => setOpenSection(prev => prev === section ? null : section)

  return (
    <div className="chat-msg chat-msg--ai">
      <div className="ai-avatar">AI</div>

      <div className="chat-content">
        {/* Answer */}
        <div className="chat-bubble chat-bubble--ai">
          <div className="ai-label">Risk Assessment</div>
          <p className="ai-answer">{answer}</p>
          <div className="ai-meta">
            <span>Confidence: <strong>{(confidence_score * 100).toFixed(0)}%</strong></span>
            <span>{retrieved_incidents?.length ?? 0} incidents retrieved</span>
          </div>
        </div>

        {/* Expandable sections */}
        <div className="chat-sections">

          {recommendations?.length > 0 && (
            <div className="chat-section">
              <button className={`section-toggle ${openSection === 'rec' ? 'open' : ''}`} onClick={() => toggle('rec')}>
                <span>💡 Recommendations ({recommendations.length})</span>
                <span className="chevron">{openSection === 'rec' ? '▲' : '▼'}</span>
              </button>
              {openSection === 'rec' && (
                <div className="section-body">
                  {recommendations.map((rec, i) => (
                    <RecommendationCard key={i} recommendation={rec} index={i} />
                  ))}
                </div>
              )}
            </div>
          )}

          {retrieved_incidents?.length > 0 && (
            <div className="chat-section">
              <button className={`section-toggle ${openSection === 'incidents' ? 'open' : ''}`} onClick={() => toggle('incidents')}>
                <span>📋 Retrieved Incidents ({retrieved_incidents.length})</span>
                <span className="chevron">{openSection === 'incidents' ? '▲' : '▼'}</span>
              </button>
              {openSection === 'incidents' && (
                <div className="section-body">
                  <IncidentTable incidents={retrieved_incidents} title="" />
                </div>
              )}
            </div>
          )}

          {agent_findings && Object.keys(agent_findings).length > 0 && (
            <div className="chat-section">
              <button className={`section-toggle ${openSection === 'agents' ? 'open' : ''}`} onClick={() => toggle('agents')}>
                <span>🔍 Agent Analysis Trace</span>
                <span className="chevron">{openSection === 'agents' ? '▲' : '▼'}</span>
              </button>
              {openSection === 'agents' && (
                <div className="section-body">
                  <AgentTrace
                    agentFindings={agent_findings}
                    anomalyCorrelations={anomaly_correlations || []}
                    confidence={confidence_score}
                  />
                </div>
              )}
            </div>
          )}

        </div>
      </div>
    </div>
  )
}
